package com.greenpulse.controller;
import com.greenpulse.common.ApiEnvelope;import com.greenpulse.domain.EnergyReading;import com.greenpulse.service.ReadingService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.time.LocalDate;import java.math.BigDecimal;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.apache.commons.csv.*;
import org.springframework.security.access.prepost.PreAuthorize;
@RestController @RequestMapping("/api/v1")
public class ReadingController {
 private final ReadingService service;public ReadingController(ReadingService service){this.service=service;}
 record CreateReading(@NotNull Long buildingId,@NotNull LocalDate readingDate,@NotNull @DecimalMin("0.0") BigDecimal energyConsumedKwh){}
 @PostMapping("/energy-readings") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN','BUILDING_MANAGER')") public ApiEnvelope<?> create(@Valid @RequestBody CreateReading x){return ApiEnvelope.ok("Reading created",dto(service.create(x.buildingId(),x.readingDate(),x.energyConsumedKwh(),"MANUAL")));}
 @GetMapping("/energy-readings") public ApiEnvelope<?> list(@RequestParam(required=false) Long buildingId,@RequestParam(defaultValue="2000-01-01") @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam(defaultValue="2099-12-31") @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return ApiEnvelope.ok("Energy readings",service.list(buildingId,from,to).stream().map(this::dto).toList());}
 @GetMapping("/buildings/{id}/energy-readings") public ApiEnvelope<?> building(@PathVariable Long id){return ApiEnvelope.ok("Building readings",service.byBuilding(id).stream().map(this::dto).toList());}
 @PostMapping(value="/energy-readings/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN','BUILDING_MANAGER')") public ApiEnvelope<?> upload(@RequestParam Long buildingId,@RequestPart MultipartFile file){int ok=0;var errors=new ArrayList<String>();try(var parser=CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build().parse(new InputStreamReader(file.getInputStream(),StandardCharsets.UTF_8))){for(var row:parser){try{service.create(buildingId,LocalDate.parse(row.get("reading_date")),new BigDecimal(row.get("energy_consumed_kwh")),"CSV");ok++;}catch(Exception ex){errors.add("row "+(row.getRecordNumber()+1)+": "+ex.getMessage());}}}catch(IOException e){throw new IllegalArgumentException("Unable to read CSV file");}return ApiEnvelope.ok("CSV processed",Map.of("successfulRows",ok,"failedRows",errors.size(),"errors",errors));}
 private Map<String,Object> dto(EnergyReading r){return Map.of("id",r.getId(),"buildingId",r.getBuilding().getId(),"buildingName",r.getBuilding().getName(),"readingDate",r.getReadingDate().toString(),"energyConsumedKwh",r.getEnergyConsumedKwh(),"source",r.getSource());}
}
